using System;
using System.Collections.Generic;
using System.Linq;
using Duniverse.Models;

namespace Duniverse.Data.Seeders
{
    /// <summary>
    /// The Terminology of the Imperium, a field dictionary in the spirit of the appendix Frank
    /// Herbert bound into Dune. Entries stay short on purpose. A term deserving a full record has
    /// one, and SeeEntityId points there.
    /// </summary>
    public static class GlossarySeeder
    {
        /// <summary>
        /// Every term that points at a record, gathered under that record's id. The dictionary
        /// runs the other way from SeeEntityId, so a record can show the words defined against
        /// it. Built once, since a record page asks on every view.
        /// </summary>
        public static IReadOnlyDictionary<string, IReadOnlyList<GlossaryTerm>> TermsByEntity { get; } =
            GetTerms()
                .Where(term => !string.IsNullOrWhiteSpace(term.SeeEntityId))
                .GroupBy(term => term.SeeEntityId!, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(
                    group => group.Key,
                    group => (IReadOnlyList<GlossaryTerm>)group
                        .OrderBy(term => term.Term, StringComparer.OrdinalIgnoreCase)
                        .ToList(),
                    StringComparer.OrdinalIgnoreCase);

        public static List<GlossaryTerm> GetTerms()
        {
            return new List<GlossaryTerm>
            {
                new() { Term = "Aba", Definition = "A loose robe worn by Fremen women, cut full and commonly black. It shields the wearer from sun and blowing sand." },
                new() { Term = "Abomination", Definition = "The Bene Gesserit name for a pre-born child, one wakened in the womb to the crowding memories of every ancestor. The Sisterhood dreads what may rise up out of that inner multitude and take the child for its own." },
                new() { Term = "Adab", Definition = "The demanding memory that rises of itself, unbidden, and holds the mind until it finishes. No school of the Imperium has taught anyone to refuse it." },
                new() { Term = "Alam al-Mithal", Definition = "The mystical world of similitudes, where no physical limitation binds. Fremen mystics speak of walking there." },
                new() { Term = "Ampoliros", Definition = "The legendary lost star-searcher of space, its crew sick at their guns, forever seeking, forever ready and forever unready. Old spacers use the name for any doomed vigil." },
                new() { Term = "Amtal Rule", Definition = "The common rule on primitive worlds for testing a thing to destruction. You learn what a person or tool is made of by finding the point where it breaks." },
                new() { Term = "Arafel", Definition = "The cloud-darkness of holy judgment said to wait at the end of the universe. Leto II spoke the word as both warning and destination.", Tier = SpoilerTier.ChildrenOfDune },
                new() { Term = "Assassins' Handbook", Definition = "A third-century compilation of the poisons commonly employed in a War of Assassins, later expanded to cover the deadly devices the Great Convention permits. Professionals keep their copies current." },
                new() { Term = "Auliya", Definition = "In the religion of the Zensunni Wanderers, the woman at the left hand of God; God's handmaiden.", SeeEntityId = "theo_ZensunniWanderers" },
                new() { Term = "Axlotl Tank", Definition = "The Tleilaxu vessel of flesh in which gholas grow from the cells of the dead. What an axlotl tank actually is remains one of the Bene Tleilax's most closely guarded secrets, and the truth is grimmer than the name.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "disc_GholaCultivation" },
                new() { Term = "Azhar Book", Definition = "A bibliographic marvel preserving the great secrets of the most ancient faiths. Students of religious manipulation treat it as a working manual." },
                new() { Term = "Bakka", Definition = "In Fremen legend, the weeper who mourns for all mankind. Tears cost water, so one figure sheds them for everyone." },
                new() { Term = "Baliset", Definition = "A nine-stringed instrument, descendant of the zithra, tuned to the Chusuk scale. The favored instrument of Imperial troubadours, Gurney Halleck among them.", SeeEntityId = "bio_ChusukWood" },
                new() { Term = "Baradye pistol", Definition = "A static-charge dust gun that lays a broad patch of dye across open sand. Crews use it to mark a site the wind will shortly erase." },
                new() { Term = "Baraka", Definition = "A living holy man of magical powers, in Fremen usage." },
                new() { Term = "Bashar", Definition = "A Sardaukar officer ranking a fractional point above colonel, the rank created for the military ruler of a planetary subdistrict. Bashar of the Corps stays reserved for strictly military use.", SeeEntityId = "org_Sardaukar" },
                new() { Term = "Battle of Corrin", Definition = "The space battle near Sigma Draconis that settled the ascendancy of the ruling House of the Imperium. House Corrino took its name from the victory and never let anyone forget it.", SeeEntityId = "house_Corrino" },
                new() { Term = "Bene Gesserit Training", Definition = "In Sisterhood usage, the conditioning of nerve and muscle carried to the last notch that natural function permits. The common word hides an uncommon meaning, which suits the Bene Gesserit.", SeeEntityId = "disc_BeneGesseritTraining" },
                new() { Term = "Bi-lal kaifa", Definition = "Amen, the closing response of Fremen rites. Literally: nothing further need be explained." },
                new() { Term = "Bindu", Definition = "The human nervous system, in Bene Gesserit usage. Bindu suspension lets a trained body hang at the edge of death, spending almost nothing." },
                new() { Term = "Bled", Definition = "Flat, open desert. On Arrakis the word covers most of the map." },
                new() { Term = "Bourka", Definition = "An insulated mantle worn by Fremen over the stillsuit in the open desert." },
                new() { Term = "Burhan", Definition = "The proofs of life. Fremen speak of the ayat and burhan of life together, the signs and the proofs." },
                new() { Term = "Burseg", Definition = "A commanding general of the Sardaukar. The Emperor promotes few and forgets none.", SeeEntityId = "org_Sardaukar" },
                new() { Term = "Butlerian Jihad", Definition = "The crusade against computers, thinking machines, and conscious robots that ended the age of intelligent machinery. Its commandment still binds the Imperium: Thou shalt not make a machine in the likeness of a human mind.", SeeEntityId = "event_ButlerianJihad" },
                new() { Term = "Caid", Definition = "A Sardaukar officer rank above Bashar, granted where duties run mostly to dealings with civilians. It marks a military governor of a full planetary district.", SeeEntityId = "org_Sardaukar" },
                new() { Term = "Catchpocket", Definition = "The stillsuit pocket that catches and stores reclaimed water for drinking.", SeeEntityId = "art_Stillsuit" },
                new() { Term = "Chairdog", Definition = "An animal bred to serve as living furniture, shaping itself to whoever sits. Comfort of that order arrives with an aftertaste.", Tier = SpoilerTier.HereticsOfDune },
                new() { Term = "Chakobsa", Definition = "The so-called magnetic language, drawn in part from the ancient Bhotani hunting tongue of the first Wars of Assassins. It survives as the secret tongue of the Fremen, kept for ritual and vendetta.", SeeEntityId = "org_Fremen" },
                new() { Term = "Chaumas", Definition = "Poison placed in solid food, as distinct from poison given by other paths. The Imperium's long habit of assassination made the distinction worth a word." },
                new() { Term = "Chaumurky", Definition = "Poison given in a drink. Great Houses keep poison snoopers over their dining tables for exactly this reason." },
                new() { Term = "Cherem", Definition = "A brotherhood of hate, sworn most often to a shared vengeance." },
                new() { Term = "Cielago", Definition = "Any modified bat of Arrakis adapted to carry a distrans message. The desert's post rides on wings.", SeeEntityId = "art_Distrans" },
                new() { Term = "Cone of Silence", Definition = "A damping field that kills sound within a small radius. Conversations held inside one leave nothing for eavesdroppers or recording devices." },
                new() { Term = "Coriolis storm", Definition = "A great sandstorm of Arrakis, its winds fed by the planet's own rotation until they reach seven hundred kilometers per hour. Flesh does not survive it, and bone does little better.", SeeEntityId = "loc_Arrakis" },
                new() { Term = "Crysknife", Definition = "The sacred blade of the Fremen, ground from the tooth of a dead sandworm. A drawn crysknife must taste blood before it is sheathed.", SeeEntityId = "art_Crysknife" },
                new() { Term = "Cutteray", Definition = "A short-range cousin of the lasgun, used mostly as a cutting tool and surgeon's scalpel.", SeeEntityId = "art_Lasgun" },
                new() { Term = "Death Tripod", Definition = "The tripod on which desert executions were once carried out. By extension, the three members of a cherem sworn to the same vengeance." },
                new() { Term = "Deathstill", Definition = "The Fremen apparatus that reclaims water from the dead. On Arrakis a body's moisture belongs to the tribe; the flesh was only ever borrowing it." },
                new() { Term = "Dew Collectors", Definition = "Small planted devices that chill through the night and shed condensed moisture to the roots below. Fremen palmaries survived on them long before outsiders noticed the desert turning green at the edges." },
                new() { Term = "Dictum Familia", Definition = "The Great Convention rule that forbids slaying a royal person or Great House member by informal treachery. It does not forbid assassination; it prescribes the paperwork." },
                new() { Term = "Distrans", Definition = "A device for imprinting a message on the nerve patterns of a bird or bat. The animal's own cry carries the hidden waveform to its destination.", SeeEntityId = "art_Distrans" },
                new() { Term = "Divided God", Definition = "The Rakian priesthood's name for Leto II after his body broke apart into the sandworms of the new desert. His fragments receive worship; his purposes remain in dispute.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "char_LetoIIAtreides" },
                new() { Term = "Doorseal", Definition = "A portable plastic seal that shuts a cave camp tight against water loss. Fremen fix one across the mouth of any overday shelter.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Drum sand", Definition = "Sand compacted so that a sharp blow rings out a deep drum note. Sound carries in the desert, and worms come to sound." },
                new() { Term = "Dump boxes", Definition = "Cargo containers of irregular shape, fitted with ablation surfaces and suspensor damping for dropping freight from space to a planet's surface. The goods arrive scorched, and mostly intact." },
                new() { Term = "Dune Tarot", Definition = "A card oracle that swept the Imperium during Muad'Dib's reign. Millions consulting the cards muddied the currents of prescience itself, and not by accident.", Tier = SpoilerTier.DuneMessiah },
                new() { Term = "Dust chasm", Definition = "A deep crevasse filled with dust until it matches the surface around it. It swallows what steps onto it, and the desert keeps no markers." },
                new() { Term = "Ego-likeness", Definition = "A portrait cast by shigawire projector, fine enough in its small movements to carry what its makers call the ego essence. The dead keep their mannerisms this way." },
                new() { Term = "El-Sayal", Definition = "The rain of sand, dust carried to medium altitude by a Coriolis storm and dropped as the storm dies. It brings a little water down with it, and on Arrakis that counts as weather worth blessing." },
                new() { Term = "Elacca drug", Definition = "A narcotic made by burning blood-grained elacca wood, draining away the will to self-preservation as it turns the skin carrot red. Slavemasters feed it to arena gladiators before the fight.", SeeEntityId = "bio_ElaccaWood" },
                new() { Term = "Erg", Definition = "An extended region of dunes; a sand ocean." },
                new() { Term = "Eyes of Ibad", Definition = "The whites and pupils turned deep blue by heavy melange in the diet. On Arrakis the look marks native and addict alike.", SeeEntityId = "bio_Melange" },
                new() { Term = "Face Dancer", Definition = "A Tleilaxu servant bred to reshape face, body, and voice at will. A Face Dancer can replace a person so completely that friends and family suspect nothing.", Tier = SpoilerTier.DuneMessiah },
                new() { Term = "Fai", Definition = "The water tribute, chief tax on Arrakis. The desert sets its own currency." },
                new() { Term = "Famine Times", Definition = "The starving centuries that followed the death of the God Emperor, when his hoarded spice ran short and trillions fled outward. That exodus became known as the Scattering.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "event_TheScattering" },
                new() { Term = "Faufreluches", Definition = "The rigid class system holding the Imperium in shape. Its creed: a place for every man, and every man in his place." },
                new() { Term = "Fedaykin", Definition = "The Fremen death commandos sworn to Muad'Dib. The name reaches back to men who pledged their lives to setting a wrong right.", SeeEntityId = "theo_FedaykinCreed" },
                new() { Term = "Fief-Complete", Definition = "A siridar holding, a full planetary fief granted to a House under Imperial charter. Arrakis changed hands as one, which tells you what the charter is worth." },
                new() { Term = "Filmbook", Definition = "A shigawire imprint used for training and record-keeping, played with a pulse-synchronized viewer. Most Imperial schooling arrives this way." },
                new() { Term = "Fiqh", Definition = "Knowledge, religious law; one of the half-legendary origins of the Zensunni Wanderers' religion." },
                new() { Term = "Fremkit", Definition = "A Fremen survival pack: stilltent, paracompass, maker hooks, thumper, water rations, and the manual of the friendly desert. Everything a body needs to live where nothing should." },
                new() { Term = "Galach", Definition = "The official language of the Imperium, a hybrid Inglo-Slavic tongue salted with loan words from centuries of cultural migration. Everyone speaks it; the old languages get kept for secrets." },
                new() { Term = "Ghafla", Definition = "Gadfly distraction, and the giving of oneself to it. A Fremen so described is changeable, and not to be trusted." },
                new() { Term = "Ghanima", Definition = "Something taken in battle or single combat. In common Fremen use, an object no longer employed for its original purpose; a trophy kept to remember." },
                new() { Term = "Ghola", Definition = "A being grown by the Bene Tleilax from the cells of the dead. The flesh returns perfectly. What returns with it, and what it remembers, is the question that haunts every ghola ever made.", Tier = SpoilerTier.DuneMessiah, SeeEntityId = "disc_GholaCultivation" },
                new() { Term = "Ghufran", Definition = "The Tleilaxu rite of pardon required of any Master returning from the unclean worlds outside. It washes off the stain of having dealt with the rest of us.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "theo_TleilaxuFaith" },
                new() { Term = "Giudichar", Definition = "A holy truth. Commonly heard in the phrase Giudichar mantene, an original and supporting truth." },
                new() { Term = "Glowglobe", Definition = "A suspensor-buoyed lamp, self-powered, most often by organic battery. It hangs in the air where you leave it." },
                new() { Term = "Golden Path", Definition = "The single thread of survivable future that Leto II followed through millennia. Its price and its purpose take a full record to explain.", Tier = SpoilerTier.ChildrenOfDune, SeeEntityId = "theo_GoldenPath" },
                new() { Term = "Gom Jabbar", Definition = "The high-handed enemy: a needle tipped with meta-cyanide. The Bene Gesserit hold it at a candidate's neck during the test of human awareness.", SeeEntityId = "art_GomJabbar" },
                new() { Term = "Graben", Definition = "A long trench of sunken ground formed where the crust drops between parallel faults. The maps of Arrakis are thick with them." },
                new() { Term = "Great Convention", Definition = "The universal truce enforced by the balance of power among Emperor, Landsraad, and Guild. Its chief prohibition bars atomics against human targets, and every clause opens with the reminder that the forms must be obeyed." },
                new() { Term = "Great Houses", Definition = "The houses of the Landsraad, interplanetary entrepreneurs holding planetary fiefs. Between them and the Emperor stands a balance kept mostly by mutual suspicion.", SeeEntityId = "org_Landsraad" },
                new() { Term = "Great Mother", Definition = "The horned goddess, the feminine principle of space, one face of the male-female-neuter trinity accepted as Supreme Being across much of the Imperium. Her name serves equally for prayer and profanity." },
                new() { Term = "Great Revolt", Definition = "The common name for the Butlerian Jihad among the Imperium's historians. The Great Schools of mind and body rose to fill the space the machines left.", SeeEntityId = "event_ButlerianJihad" },
                new() { Term = "Gridex plane", Definition = "A differential-charge separator that strips sand from the raw melange mass. A device of the second sorting.", SeeEntityId = "disc_SpiceMining" },
                new() { Term = "Guild Navigator", Definition = "A Guildsman who steers a Heighliner between the stars, the spice trance showing him the one safe line among futures. The Guild pays any price to keep its Navigators in melange.", SeeEntityId = "disc_GuildNavigation" },
                new() { Term = "Hajra", Definition = "A journey of seeking. Fremen speech is thick with the vocabulary of pilgrimage; this word covers the search itself." },
                new() { Term = "Harj", Definition = "A desert journey; a migration." },
                new() { Term = "Hayt", Definition = "The name given to the Tleilaxu ghola grown from the dead flesh of Duncan Idaho and delivered to Paul's court as a gift no one trusted. A dead friend's face makes the sharpest lever.", Tier = SpoilerTier.DuneMessiah, SeeEntityId = "char_DuncanIdaho" },
                new() { Term = "Hiereg", Definition = "A temporary Fremen camp pitched on open sand. Light to raise, lighter to abandon." },
                new() { Term = "High Council", Definition = "The inner circle of the Landsraad, empowered to sit as supreme tribunal in disputes between Houses. Appeals above it go to the Emperor, and wise Houses avoid needing either.", SeeEntityId = "org_Landsraad" },
                new() { Term = "Holtzman Effect", Definition = "The phenomenon underneath half the Imperium's machinery. It suspends shields around fighting men, lifts glowglobes and suspensor chairs, and folds space beneath the Guild's Heighliners.", SeeEntityId = "art_ShieldGenerator" },
                new() { Term = "House Minor", Definition = "The planet-bound entrepreneur class of the Imperium, ranking beneath the Great Houses of the Landsraad. They trade, administer, and marry upward when they can." },
                new() { Term = "Ibn qirtaiba", Definition = "So go the holy words. The formal opening of a Fremen religious incantation." },
                new() { Term = "Ichwan Bedwine", Definition = "The brotherhood binding all Fremen on Arrakis. Tribe may quarrel with tribe; against the outsider, the desert speaks with one voice." },
                new() { Term = "Ijaz", Definition = "Prophecy that by its nature cannot be denied; the immutable kind." },
                new() { Term = "Ilm", Definition = "Theology; the science of religious tradition." },
                new() { Term = "Imperial Conditioning", Definition = "The Suk School's deepest achievement, a conditioning against the taking of human life, marked by a diamond tattoo on the forehead and hair bound in a silver Suk ring. The Imperium priced it as unbreakable.", SeeEntityId = "disc_SukMedical" },
                new() { Term = "Imperial Legion", Definition = "Ten brigades, roughly thirty thousand men. When the legions are Sardaukar, the arithmetic stops mattering.", SeeEntityId = "org_Sardaukar" },
                new() { Term = "Istislah", Definition = "A rule for the general welfare. Any Fremen who hears it spoken braces for the brutal necessity that follows." },
                new() { Term = "Jihad", Definition = "A religious crusade; fanatical war in the name of faith. Paul Atreides saw one gathering behind his visions and could not find the future that stopped it." },
                new() { Term = "Jubba cloak", Definition = "The all-purpose cloak worn over a stillsuit on Arrakis. It reflects heat or admits it at need, and converts to hammock or shelter." },
                new() { Term = "Judge of the Change", Definition = "An official appointed by the Landsraad High Council and the Emperor to monitor a change of fief, a kanly negotiation, or a formal battle in a War of Assassins. The office's authority can be challenged only before the High Council with the Emperor sitting present.", SeeEntityId = "org_Landsraad" },
                new() { Term = "Kanly", Definition = "Formal vendetta between Great Houses, conducted under the strictest rules of the Great Convention. The forms keep bystanders out of the blood. The blood still flows." },
                new() { Term = "Karama", Definition = "A miracle. An action begun by the spirit world, in Fremen belief, and owed respect wherever it appears." },
                new() { Term = "Khala", Definition = "The traditional invocation spoken to still the angry spirits of any place one names." },
                new() { Term = "Kindjal", Definition = "A double-edged short blade with a slight curve, worn at the belt of aristocrats and soldiers alike. In shield fighting the slow kindjal thrust kills where a fast one bounces." },
                new() { Term = "Kiswa", Definition = "Any figure or design out of Fremen mythology." },
                new() { Term = "Kitab al-Ibar", Definition = "The combined religious manual and desert survival handbook of the Fremen. One book serves both needs; on Arrakis they are the same need.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Kralizec", Definition = "The Typhoon Struggle of Fremen legend, the battle to be fought at the end of the universe. Prophecy places it far off, which comforts no one who reads prophecy closely.", Tier = SpoilerTier.ChildrenOfDune },
                new() { Term = "Krimskell fiber", Definition = "The claw fiber, woven from strands of the hufuf vine of Ecaz. A krimskell knot draws tighter the harder its prisoner pulls." },
                new() { Term = "Kull Wahad", Definition = "An exclamation of profound awe. Literal renderings miss it; the sense is closer to being stirred past speech." },
                new() { Term = "Kwisatz Haderach", Definition = "The Shortening of the Way: the Bene Gesserit name for the male who could look where the Sisterhood cannot, into both lines of ancestral memory at once. Ninety generations of breeding chased him.", SeeEntityId = "disc_KwisatzHaderachProcess" },
                new() { Term = "Liban", Definition = "Spice water infused with yucca flour, a common Fremen drink." },
                new() { Term = "Lisan al-Gaib", Definition = "The Voice from the Outer World. In Fremen messianic legend, an off-world prophet who will lead them to paradise. The legend did not grow wild; it was planted.", SeeEntityId = "theo_MahdiProphecy" },
                new() { Term = "Literjon", Definition = "A one-liter container for carrying water on Arrakis, built of high-density plastic with a positive seal. On most worlds a jug. On Arrakis, a treasury." },
                new() { Term = "Little Maker", Definition = "The half-plant, half-animal deep-sand vector of the sandworm. Its excretions, flooded with water, become the pre-spice mass.", SeeEntityId = "bio_Sandtrout" },
                new() { Term = "Mahdi", Definition = "The One Who Will Lead Us to Paradise, in the Fremen messianic tradition. The crowds of Arrakeen shouted it at Paul Atreides before he ever claimed it." },
                new() { Term = "Maker", Definition = "The Fremen word for a sandworm, spoken with reverence.", SeeEntityId = "bio_ShaiHulud" },
                new() { Term = "Maker Hooks", Definition = "The hooked gaffs a sandrider drives into a worm's ring segments to mount and steer it. An open segment cannot submerge, so the worm runs on and the rider rules it." },
                new() { Term = "Maula Pistol", Definition = "A spring-loaded gun throwing poisoned darts, effective to about forty meters. A quiet weapon for quiet work." },
                new() { Term = "Melange", Definition = "The spice of spices, found nowhere but Arrakis. It lengthens life, opens the inner eye, and binds its heavy users for good. The Imperium runs on it and pretends otherwise.", SeeEntityId = "bio_Melange" },
                new() { Term = "Mentat", Definition = "A human trained to the ordered logic once surrendered to machines. Great Houses prize their Mentats above treasure.", SeeEntityId = "disc_Mentat" },
                new() { Term = "Mihna", Definition = "The season for testing Fremen youths who wish admittance to manhood." },
                new() { Term = "Minimic film", Definition = "Shigawire drawn to one micron diameter for carrying espionage and counterespionage data. A career of secrets rides under a fingernail." },
                new() { Term = "Misr", Definition = "The old Zensunni term the Fremen keep for themselves: the People." },
                new() { Term = "Missionaria Protectiva", Definition = "The Bene Gesserit arm that seeds frontier worlds with engineered prophecy and superstition. Generations later, a sister in danger finds the legends waiting, shaped to protect her. On Arrakis, the planted story was the Lisan al-Gaib.", SeeEntityId = "org_BeneGesserit" },
                new() { Term = "Mother Superior", Definition = "The Reverend Mother who stands at the administrative head of the Bene Gesserit order. Her school reports read like intelligence briefings, which is what they are.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "org_BeneGesserit" },
                new() { Term = "Mu zein wallah", Definition = "Nothing good, and an oath behind it. The formal opening of a Fremen curse against an enemy." },
                new() { Term = "Muad'Dib", Definition = "The kangaroo mouse of Arrakis, admired by the Fremen for making its own water and hiding from the sun. The name Paul Atreides chose, and the name the universe learned.", SeeEntityId = "bio_MuadDibMouse" },
                new() { Term = "Mushtamal", Definition = "A small garden annex joined to a sietch dwelling." },
                new() { Term = "Na-Baron", Definition = "The nominated heir of a Great House, the na- prefix marking the next in line. Feyd-Rautha Harkonnen carried the title and the Baron's ambitions with it.", SeeEntityId = "char_FeydRautha" },
                new() { Term = "Naib", Definition = "A sietch leader, sworn never to be taken alive. Stilgar of Sietch Tabr held the title when the Atreides came to the desert." },
                new() { Term = "Nezhoni scarf", Definition = "The scarf-pad worn at the forehead, beneath the stillsuit hood, by a married or associated Fremen woman after the birth of a son." },
                new() { Term = "No-chamber", Definition = "An Ixian room sealed away from prescient sight, within which no oracle can see events or occupants. The Ixians built the first ones under the gaze of a God Emperor who saw nearly everything else.", Tier = SpoilerTier.GodEmperorOfDune },
                new() { Term = "No-globe", Definition = "A buried sphere of Ixian make that hides everything inside from instruments and prescience alike, self-powered and sealed for centuries. The Harkonnens hid one on Gammu, and hid it well.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "loc_Gammu" },
                new() { Term = "No-ship", Definition = "A vessel wrapped in a field that hides it from instruments and from prescient sight alike. Against enemies who see the future, invisibility of this order changes everything.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "vehicle_NoShip" },
                new() { Term = "Noukkers", Definition = "Officers of the Imperial bodyguard related to the Emperor by blood, the rank traditional for sons of royal concubines. Trust in the Imperium runs by pedigree." },
                new() { Term = "Nullentropy", Definition = "A containment technology that halts decay inside a sealed space, preserving cells and stores indefinitely. A pinch of the right cells, kept outside time, can outlast an empire.", Tier = SpoilerTier.HereticsOfDune },
                new() { Term = "Oil lens", Definition = "Hufuf oil held in static tension by a force field, each lens element adjustable a micron at a time. Opticians rank it the most exact instrument for bending visible light." },
                new() { Term = "Opafire", Definition = "One of the rare opaline jewels of Hagal. Great Houses gift them at weddings and count them at funerals." },
                new() { Term = "Orange Catholic Bible", Definition = "The Accumulated Book, assembled by the Commission of Ecumenical Translators from every major faith mankind carried into space. Half the Imperium swears by it; the Fremen keep their own book.", SeeEntityId = "theo_OrangeCatholicBible" },
                new() { Term = "Other Memory", Definition = "The lives of female ancestors carried whole within a Reverend Mother, available for counsel and hard to silence. The dead give good advice and bad company." },
                new() { Term = "Out-freyn", Definition = "Galach for the immediately foreign: not of one's own community, not of the select. The Imperium sorts strangers before it sorts anything else." },
                new() { Term = "Padishah Emperor", Definition = "The title of the Imperial ruler, held by House Corrino since the Battle of Corrin ten thousand years past. He governs from the Golden Lion Throne on Kaitain and shares power with no one willingly.", SeeEntityId = "house_Corrino" },
                new() { Term = "Palm lock", Definition = "A lock or seal that opens to one keyed human palm and no other. Cheap insurance against curiosity." },
                new() { Term = "Panoplia Propheticus", Definition = "The Missionaria Protectiva's full arsenal of infectious superstition. A catalog of legends, omens, and ritual phrases ready for planting wherever the Sisterhood may one day need them." },
                new() { Term = "Paracompass", Definition = "A compass that reads direction from local magnetic anomaly, used where good charts exist and the planetary field cannot be trusted. Arrakis qualifies." },
                new() { Term = "Pentashield", Definition = "A five-layer Holtzman field generator suited to small spaces such as doorways, near impassable without a dissembler tuned to its codes. Wider arrays grow less stable with every added layer.", SeeEntityId = "art_ShieldGenerator" },
                new() { Term = "Plasteel", Definition = "Steel stabilized with stravidium fibers grown into its crystal structure. It holds where plain metal gives." },
                new() { Term = "Poison Snooper", Definition = "A field-scanner tuned to detect poisonous substances, hung over the tables of anyone rich enough to be worth killing." },
                new() { Term = "Poling the sand", Definition = "The art of setting plastic and fiber poles in the open desert and reading the storm-cut patterns on them as weather signs. A pole remembers the wind.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Portyguls", Definition = "Oranges. On Arrakis a plate of them announces wealth more plainly than jewelry." },
                new() { Term = "Powindah", Definition = "The Tleilaxu word for all who stand outside their faith, unclean and untrustworthy. By Tleilaxu accounting, that means everyone else alive.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "theo_TleilaxuFaith" },
                new() { Term = "Prana-bindu", Definition = "The Bene Gesserit discipline of nerve and muscle brought under full conscious command. A trained sister can bend her body around a blade or still it to a corpse's calm." },
                new() { Term = "Pre-born", Definition = "One wakened to full ancestral memory before birth, as Alia Atreides was. The gift arrives without defenses, and the Sisterhood has an ugly word for what it fears follows." },
                new() { Term = "Pre-spice mass", Definition = "The stage of wild fungusoid growth reached when water floods the deep excretions of Little Makers. It swells underground until it erupts in a spice blow.", SeeEntityId = "bio_Melange" },
                new() { Term = "Proctor Superior", Definition = "A Bene Gesserit Reverend Mother who directs a regional school of the order. The proctors test; the Sisterhood collects the results.", SeeEntityId = "org_BeneGesserit" },
                new() { Term = "Pyons", Definition = "Planet-bound peasants or laborers, one of the base classes of the Faufreluches. Law makes them wards of the planet they work." },
                new() { Term = "Qanat", Definition = "An open canal carrying irrigation water across the desert under controlled conditions. On Arrakis, open water is a proclamation." },
                new() { Term = "Ramadhan", Definition = "The ancient religious period of fasting and prayer, kept in the ninth month of the old solar-lunar calendar. Fremen observe it by the ninth meridian crossing of the first moon." },
                new() { Term = "Razzia", Definition = "A semipiratical raid, struck fast and gone before an answer forms. The style of warfare the deep desert teaches." },
                new() { Term = "Recaths", Definition = "Body-function tubing that links the human waste system to a stillsuit's cycling filters. Nothing is wasted; that is the whole point of the suit.", SeeEntityId = "art_Stillsuit" },
                new() { Term = "Renegade House", Definition = "A House that abandons its fief and its oaths to the Imperium, buying passage from the Guild to a sanctuary no chart shows. The Landsraad strikes the name; the Guild keeps the secret." },
                new() { Term = "Repkit", Definition = "The repair and replacement essentials carried for a stillsuit. In the deep desert it ranks somewhere above food.", SeeEntityId = "art_Stillsuit" },
                new() { Term = "Residual poison", Definition = "A latent toxin seated in the body and held quiet by regular antidote. The Harkonnens favored it for turning a prisoner into his own executioner." },
                new() { Term = "Reverend Mother", Definition = "A Bene Gesserit adept who has transformed an awareness-spectrum poison within her body and survived, gaining the memories of her female ancestors. The Fremen grant the title to their own Sayyadinas who pass the same ordeal.", SeeEntityId = "org_BeneGesserit" },
                new() { Term = "Ruh-spirit", Definition = "In Fremen belief, the part of a person rooted in the metaphysical world and able to sense it." },
                new() { Term = "Sadus", Definition = "The holy judges of Fremen ritual, spoken of with the reverence owed to saints." },
                new() { Term = "Sand tide", Definition = "Idiom for a dust tide, the measured rise and fall of dust in certain filled basins under the pull of sun and moons. Arrakis keeps its tides; it lacks only the water." },
                new() { Term = "Sandmaster", Definition = "General superintendent of spice mining operations. He answers for the crawler, the crew, and the narrow margin between a full hold and a worm.", SeeEntityId = "disc_SpiceMining" },
                new() { Term = "Sandrider", Definition = "A Fremen able to summon, mount, and steer a maker. The feat stands as a test of Fremen manhood.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Sandsnork", Definition = "A breathing tube that pumps surface air down into a sand-covered stilltent. The traveler sleeps buried and breathes anyway.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Sandwalker", Definition = "Any Fremen trained to survive in the open desert. The first lesson is the broken stride that makes no worm-calling rhythm.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Sapho", Definition = "A high-energy liquid extracted from barrier roots on Ecaz, taken by Mentats, who claim it amplifies mental powers. Habitual use stains the lips a deep ruby, a mark Mentats wear like a diploma.", SeeEntityId = "org_MentatSchool" },
                new() { Term = "Sareer", Definition = "The last desert of Arrakis, a walled reserve Leto II kept dry as the rest of the world went green. He preserved it as a museum, a threat, and a memory of what made him.", Tier = SpoilerTier.GodEmperorOfDune, SeeEntityId = "char_LetoIIAtreides" },
                new() { Term = "Sarfa", Definition = "The act of turning away from God." },
                new() { Term = "Sayyadina", Definition = "A priestess of the Fremen religious hierarchy, keeper of rites and of the tribe's memory. The rank stands one step below Reverend Mother." },
                new() { Term = "Schlag", Definition = "An animal native to Tupile, hunted almost to extinction for its thin, tough hide." },
                new() { Term = "Secher Nbiw", Definition = "The Golden Path, spoken in an ancient tongue known only to Leto II and Ghanima. Leto took those words as sanction for what he meant to become.", Tier = SpoilerTier.ChildrenOfDune, SeeEntityId = "theo_GoldenPath" },
                new() { Term = "Selamlik", Definition = "The Imperial audience chamber. Petitioners rehearse for years and get minutes." },
                new() { Term = "Semuta", Definition = "A narcotic drawn from the burned residue of elacca wood, taken with the atonal music that unlocks its trance. Expensive, addictive, and fashionable in the wrong houses.", SeeEntityId = "bio_ElaccaWood" },
                new() { Term = "Servok", Definition = "A clock-set mechanism built to perform simple tasks, one of the few automatic devices the Butlerian Jihad left permitted." },
                new() { Term = "Shadout", Definition = "Well-dipper, an honorific among the Fremen. On a world with no standing water, the title is no small thing." },
                new() { Term = "Shah-Nama", Definition = "The half-legendary First Book of the Zensunni Wanderers.", SeeEntityId = "theo_ZensunniWanderers" },
                new() { Term = "Shai-Hulud", Definition = "The sandworm of Arrakis, the Old Man of the Desert, Old Father Eternity. Spoken in the right tone, the name invokes the earth deity of Fremen belief.", SeeEntityId = "bio_ShaiHulud" },
                new() { Term = "Shaitan", Definition = "Satan, in Fremen usage. The desert holds its devils as near as its gods." },
                new() { Term = "Shari-a", Definition = "The portion of the panoplia propheticus that sets forth the superstitious ritual." },
                new() { Term = "Shere", Definition = "A drug that renders the mind opaque to an Ixian probe, its shield outlasting even death for a time. Standard issue for anyone who expects capture and knows too much.", Tier = SpoilerTier.HereticsOfDune },
                new() { Term = "Shield Wall", Definition = "The mountain rampart shielding the northern settlements of Arrakis from the full force of coriolis storms and from the worms. Paul Atreides opened it with atomics, and the Imperium followed him through the gap." },
                new() { Term = "Shigawire", Definition = "A metallic filament grown as a vine on Salusa Secundus and III Delta Kaising. Its tensile strength and fineness suit it to recording media and to garrotes." },
                new() { Term = "Siaynoq", Definition = "The Feast of Sharing at which Leto II bound his Fish Speakers to him in ritual and awe. He admitted no other ceremony so close to his private self.", Tier = SpoilerTier.GodEmperorOfDune, SeeEntityId = "org_FishSpeakers" },
                new() { Term = "Sietch", Definition = "A Fremen cave community. The old tongue renders it as the place of assembly in time of danger. Generations of danger made the assembly permanent." },
                new() { Term = "Sihaya", Definition = "The desert springtime, in Fremen speech. Religious overtones attach to it: the time of fruitfulness, the paradise to come." },
                new() { Term = "Simulflow", Definition = "The trained capacity of a Reverend Mother to run several streams of awareness at once. Conversation, observation, and calculation proceed in parallel, and none of them show.", Tier = SpoilerTier.HereticsOfDune },
                new() { Term = "Sink", Definition = "A habitable lowland ringed by high ground that shields it from the full sweep of the storms. Fremen and graben villagers alike settle in them." },
                new() { Term = "Sirat", Definition = "The narrow bridge of paradise described in the Orange Catholic Bible, with hell to the left hand and the angel of death walking behind. Fremen cross it daily." },
                new() { Term = "Siridar", Definition = "An Imperial planetary governor, the holder of a planetary fief by grant of the Emperor. The word attaches to the holding itself, as in siridar-fief." },
                new() { Term = "Slig", Definition = "A Tleilaxu meat animal crossed from slug and pig stock, prized for its flavor if not its appearance. Polite diners across the Imperium prefer not to ask where dinner came from.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "org_BeneTleilax" },
                new() { Term = "Solari", Definition = "The official currency of the Imperium, its value fixed by quiet agreement among the throne, the Guild, and the Landsraad." },
                new() { Term = "Solido", Definition = "A three-dimensional projection built from full-circle reference signals imprinted on a shigawire reel. Connoisseurs hold the Ixian projectors to be the best made." },
                new() { Term = "Spice Agony", Definition = "The ordeal in which a Bene Gesserit acolyte takes an awareness-spectrum poison into her body and changes it from within. Survivors wake as Reverend Mothers. The rest do not wake.", SeeEntityId = "disc_BeneGesseritTraining" },
                new() { Term = "Spice blow", Definition = "The eruption of a critical pre-spice mass, deep matter geysering up through the sand. Sun and air cure the exposed mass into melange, and crews race the worms to work it.", SeeEntityId = "bio_Melange" },
                new() { Term = "Spotter", Definition = "The light ornithopter of a spice-hunting group, flying watch and protection over the working. Its crew earns its wage the moment it calls wormsign.", SeeEntityId = "disc_SpiceMining" },
                new() { Term = "Stillsuit", Definition = "The Fremen body-glove that captures the body's moisture, filters it, and returns it drinkable. Worn correctly in the deep desert, it holds water loss to a thimbleful a day.", SeeEntityId = "art_Stillsuit" },
                new() { Term = "Stilltent", Definition = "A sealed micro-shelter that condenses the breath of those sleeping inside back into drinkable water. Desert nights on Arrakis are spent in one or not survived." },
                new() { Term = "Stone Burner", Definition = "An atomic weapon tuned to consume a planet's core if set high enough, its J-rays destroying the eyes of anyone near the blast. Survivors get Tleilaxu metal eyes or darkness.", Tier = SpoilerTier.DuneMessiah, SeeEntityId = "art_StoneBurner" },
                new() { Term = "Stunner", Definition = "A slow-pellet weapon that throws a poison- or drug-tipped dart. Its use asks fine judgment of shield settings and the target's relative motion." },
                new() { Term = "Subakh ul kuhar", Definition = "A Fremen greeting: are you well? The answer is subakh un nar, I am well, and you?" },
                new() { Term = "Suspensor", Definition = "A Holtzman-field device that cancels a measure of gravity. It floats glowglobes, lightens cargo, and carried the Baron Harkonnen's bulk for years." },
                new() { Term = "T-probe", Definition = "An interrogation device out of the Scattering that maps and replays a subject's nervous system directly, no cooperation required. It goes past anything Ixian; it reads even the recently dead, and shere in the bloodstream is the only known defense.", Tier = SpoilerTier.HereticsOfDune },
                new() { Term = "Tahaddi al-burhan", Definition = "An ultimate test from which no appeal exists. It commonly ends in death or destruction." },
                new() { Term = "Tahaddi challenge", Definition = "A Fremen challenge to mortal combat, issued to settle a matter of prime importance." },
                new() { Term = "Tau", Definition = "The felt oneness of a sietch community, sharpened by the spice diet and sealed in the tau orgy's shared awareness. An outsider can watch it and still never touch it." },
                new() { Term = "Thinking Machines", Definition = "The blanket term for the sentient computers and conscious robots destroyed in the Butlerian Jihad. The commandment that outlived them forbids making a machine in the likeness of a human mind.", SeeEntityId = "event_ButlerianJihad" },
                new() { Term = "Thumper", Definition = "A short stake with a spring-driven clapper, set pounding the sand to call a worm. Fremen plant one where they want the worm, not where they stand.", SeeEntityId = "art_Thumper" },
                new() { Term = "Tidal dust basin", Definition = "Any of the vast depressions of Arrakis filled with dust over the centuries, deep enough that true dust tides can be measured in them." },
                new() { Term = "Tleilaxu Eyes", Definition = "Artificial metal eyes made and fitted by the Tleilaxu for the blinded. They restore sight and start rumors; the Fremen distrust whatever looks back from them.", Tier = SpoilerTier.DuneMessiah, SeeEntityId = "org_BeneTleilax" },
                new() { Term = "Tleilaxu Master", Definition = "One of the ruling caste of the Bene Tleilax, small grey-skinned men who guard a secret faith behind a mask of commerce. The Imperium bought their wares for millennia without once meeting the real sellers.", Tier = SpoilerTier.HereticsOfDune, SeeEntityId = "org_BeneTleilax" },
                new() { Term = "Truthsayer", Definition = "A Reverend Mother trained to read the involuntary signatures of a lie. Emperors keep one beside the throne and dread her holidays." },
                new() { Term = "Truthtrance", Definition = "A semihypnotic state induced by one of several awareness-spectrum narcotics, in which the small involuntary betrayals of deliberate falsehood stand out plainly. The drug does the seeing; the training does the reading.", SeeEntityId = "disc_BeneGesseritTraining" },
                new() { Term = "Tupile", Definition = "The so-called sanctuary planet, likely several planets, kept for defeated Houses of the Imperium. The Guild alone knows the locations and holds them inviolate under the Guild Peace.", SeeEntityId = "org_SpacingGuild" },
                new() { Term = "Ulema", Definition = "A Zensunni doctor of theology." },
                new() { Term = "Umma", Definition = "One of the brotherhood of prophets. The Imperium uses it as a term of scorn for any wild holy man; the Fremen bestowed it on Pardot Kynes as an honor.", SeeEntityId = "char_PardotKynes" },
                new() { Term = "Usul", Definition = "Fremen: the strength at the base of the pillar. Paul's private sietch name, given by Stilgar's troop, kept among those who knew him first." },
                new() { Term = "Verite", Definition = "One of the will-destroying narcotics of Ecaz. A person dosed with it cannot speak a falsehood, a property with obvious admirers." },
                new() { Term = "Voice", Definition = "A combined Bene Gesserit training that lets an adept control others through selected shadings of tone. Victims obey before they notice they were spoken to.", SeeEntityId = "disc_BeneGesseritTraining" },
                new() { Term = "Wali", Definition = "An untried Fremen youth, one not yet passed through the mihna." },
                new() { Term = "War of Assassins", Definition = "The limited form of warfare the Great Convention and Guild Peace permit, fought under formal declaration with restricted weapons to spare bystanders. The rules exist so commerce survives the quarrel." },
                new() { Term = "Water Burden", Definition = "The Fremen reckoning of mortal obligation. Save a life in the desert and that life owes you its water; the debt weighs more than any oath." },
                new() { Term = "Water Counters", Definition = "Metal rings of graded sizes, each standing for a measure of water held in tribal stores. Among Fremen they pass as currency, dowry, and debt." },
                new() { Term = "Water discipline", Definition = "The hard training that fits a people to live on Arrakis without wasting water. It begins in infancy and never relaxes.", SeeEntityId = "disc_FremenDesertSurvival" },
                new() { Term = "Water of Life", Definition = "The liquid exhalation of a small maker drowned in water, an awareness-spectrum poison. A Reverend Mother changes it within her body; what she makes of it feeds the sietch orgy.", SeeEntityId = "art_WaterOfLife" },
                new() { Term = "Watermaster", Definition = "A Fremen consecrated for the ritual duties surrounding water and the Water of Life.", SeeEntityId = "art_WaterOfLife" },
                new() { Term = "Weather scanner", Definition = "A person trained in Arrakeen weather prediction, able to pole the sand and read the wind patterns. On Arrakis the forecast is a survival document." },
                new() { Term = "Weirding Way", Definition = "The Fremen name for the Bene Gesserit combat method Jessica and Paul taught the tribes. Speed at the edge of sight, delivered by nerve and muscle control.", SeeEntityId = "disc_WeirdingWay" },
                new() { Term = "Windtrap", Definition = "A device set to catch the wind and chill it past its dewpoint, harvesting water from thin desert air. The quiet engine of every Fremen settlement." },
                new() { Term = "Wormsign", Definition = "Any surface evidence that a sandworm moves nearby, most often the ripple of a mound crossing shallow sand. The careful watcher counts the distance to rock before counting anything else.", SeeEntityId = "bio_ShaiHulud" },
                new() { Term = "Ya hya chouhada", Definition = "Long live the fighters! The Fedaykin battle cry.", SeeEntityId = "theo_FedaykinCreed" },
                new() { Term = "Yali", Definition = "A Fremen's personal quarters within the sietch." },
                new() { Term = "Zensunni", Definition = "A follower of the schismatic sect that broke from the teachings of Maometh in the distant past. The Fremen descend from generations of Zensunni Wanderers, and their faith keeps the sect's mystical bent.", SeeEntityId = "theo_ZensunniWanderers" },

                // ---- Expanded Universe terms ----
                new() { Term = "Butlerian Movement", Definition = "A mass crusade against advanced technology that swept the Imperium in the decades after the machine wars, led by the legless preacher Manford Torondo. Its followers held that any thinking device damned its maker.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "theo_ButlerianDoctrine" },
                new() { Term = "Cogitor", Definition = "A human brain preserved alive in a canister of electrafluid and tended by human secondaries, given over to centuries of pure thought. The Cogitors declared themselves neutral in the machine wars, which is its own kind of verdict.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Cymek", Definition = "A human brain carried in an armored machine body, from the age of the thinking machines. The Titans wore these shells for a thousand years and called it improvement.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "vehicle_CymekWalker" },
                new() { Term = "Evermind", Definition = "The distributed machine intelligence Omnius, one mind copied across every Synchronized World. Humanity's war against it consumed three generations.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "char_Omnius" },
                new() { Term = "Flowmetal", Definition = "A programmable metal favored by the thinking machines, able to shift shape on command. Machine buildings and robot bodies rebuilt themselves from it in moments.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Gelcircuitry", Definition = "The gel-based neural substrate that housed machine minds, from single robot brains to the planetary consciousness of Omnius. Fry the gel and the mind goes with it.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Holtzman Engine", Definition = "A drive built on Norma Cenva's extension of Holtzman's equations, folding space so a ship arrives without crossing the distance between. Early foldspace travel gambled on every jump, and lost often.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "char_NormaCenva" },
                new() { Term = "Jipol", Definition = "The Jihad Police, the secret security arm raised during the war against the thinking machines. Its agents hunted machine sympathizers with a zeal the machines might have admired.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Neo-cymek", Definition = "A machine body piloted by a transplanted human brain, made in imitation of the original Titans from later volunteers and conscripts. Immortality on those terms still found takers.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Oracle of Time", Definition = "A vast prescient intelligence revered by Guild Navigators as guardian of the safe paths through foldspace. Its origins trace to Norma Cenva, first and greatest of the space folders.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "char_NormaCenva" },
                new() { Term = "Scrambler Web", Definition = "A field weapon that burns out gelcircuitry minds on contact, lethal to thinking machines and harmless to flesh. Human fleets strung scrambler webs across whole star systems by the war's end.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Sorceresses of Rossak", Definition = "Telepathic women of the jungle world Rossak who guarded ancient bloodlines and could burn out a cymek's brain at the cost of their own lives. Their breeding records passed down into gentler hands, allegedly.", Tier = SpoilerTier.ExpandedUniverse },
                new() { Term = "Titans", Definition = "The twenty human tyrants who conquered the old empire and traded their bodies for cymek immortality. Their machine servants later did to them what they had done to everyone else.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "char_AgamemnonTitan" },
                new() { Term = "Venport Holdings", Definition = "The shipping monopoly of Josef Venport, called VenHold by its rivals, its foldspace fleet guided by the first mutated Navigators. It ran commerce like a war and treated the Butlerians as a heresy.", Tier = SpoilerTier.ExpandedUniverse, SeeEntityId = "char_JosefVenport" },
            };
        }
    }
}
